void xlr8_set_runtime(runtime *rt)
// ----------------------------------------------------------------------------
//   Select the runtime used by native helper calls
// ----------------------------------------------------------------------------
{
    xlr8_current_rt = rt;
}


runtime *xlr8_get_runtime()
// ----------------------------------------------------------------------------
//   Return the runtime used by native helper calls
// ----------------------------------------------------------------------------
{
    return xlr8_current_rt;
}


void xlr8_set_sys_args(byte_p args)
// ----------------------------------------------------------------------------
//   Remember bytecode pointer for the next sys call
// ----------------------------------------------------------------------------
{
    xlr8_sys_args_pc = args;
}


void xlr8_store_float_local(byte d, uint32_t bits)
// ----------------------------------------------------------------------------
//   Write a float into a bytecode local using interpreter frame layout
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return;
    float v = 0;
    memcpy(&v, &bits, sizeof(v));
    memcpy((float *) &xlr8_current_rt->frame[d], &v, sizeof(v));
}


void *xlr8_runtime_fn(cstring name)
// ----------------------------------------------------------------------------
//   Resolve a native helper name to a function pointer
// ----------------------------------------------------------------------------
{
    struct entry { cstring name; void *fn; };
    static entry table[] = {
        { "xlr8_enter",    (void *) xlr8_enter },
        { "xlr8_leave",    (void *) xlr8_leave },
        { "xlr8_resolve",  (void *) xlr8_resolve },
        { "xlr8_sys",      (void *) xlr8_sys },
        { "xlr8_after_sys", (void *) xlr8_after_sys },
        { "xlr8_dispatch", (void *) xlr8_dispatch },
        { "xlr8_store_float_local", (void *) xlr8_store_float_local },
        { "xlr8_push_value",      (void *) xlr8_push_value },
        { "xlr8_pop_value",       (void *) xlr8_pop_value },
        { "xlr8_push_flags_val",  (void *) xlr8_push_flags_val },
        { "xlr8_pop_flags_val",   (void *) xlr8_pop_flags_val },
        { "xlr8_save_jit_link",   (void *) xlr8_save_jit_link },
        { "xlr8_load_jit_link",   (void *) xlr8_load_jit_link },
        { "xlr8_store_global",    (void *) xlr8_store_global },
        { "xlr8_load_global",     (void *) xlr8_load_global },
        { "xlr8_set_flags",       (void *) xlr8_set_flags },
        { "xlr8_get_flags",       (void *) xlr8_get_flags },
    };
    for (entry &e : table)
        if (!strcmp(e.name, name))
            return e.fn;
    return nullptr;
}


stack_p xlr8_enter(byte locals)
// ----------------------------------------------------------------------------
//   Allocate a bytecode frame with the given number of locals
// ----------------------------------------------------------------------------
{
    return xlr8_current_rt ? xlr8_current_rt->enter(locals) : nullptr;
}


stack_p xlr8_leave()
// ----------------------------------------------------------------------------
//   Pop the current bytecode frame
// ----------------------------------------------------------------------------
{
    return xlr8_current_rt ? xlr8_current_rt->leave() : nullptr;
}


byte_p xlr8_resolve(tok_t t)
// ----------------------------------------------------------------------------
//   Resolve an undefined token to its implementation address
// ----------------------------------------------------------------------------
{
    tok_t impl = 0;
    return xlr8_resolve_impl(t, &impl);
}


byte_p xlr8_resolve_impl(tok_t t, tok_t *impl_tok)
// ----------------------------------------------------------------------------
//   Resolve call/jmp target, following op_undef stubs to the implementation
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return nullptr;
    runtime &rt = *xlr8_current_rt;
    byte_p pc = nullptr;
    if (rt.resolve(t, t, pc))
    {
        if (impl_tok)
        {
            auto it = rt.defined.find(t);
            *impl_tok = (it != rt.defined.end()) ? (*it).second : t;
        }
        return pc;
    }
    byte_p tp = xlr8_bytecode_start(t);
    if (tp && *tp == runtime::op_undef)
    {
        byte_p ucp = tp + 1;
        tok_t name = leb128<tok_t>(ucp);
        if (rt.resolve(name, name, pc))
        {
            if (impl_tok)
            {
                auto it = rt.defined.find(name);
                *impl_tok = (it != rt.defined.end()) ? (*it).second : name;
            }
            return pc;
        }
    }
    if (t > 0 && t < rt.tokens.size())
    {
        pc = byte_p(rt.tok(t));
        if (pc && *pc != runtime::op_undef)
        {
            if (impl_tok)
                *impl_tok = t;
            return pc;
        }
    }
    return nullptr;
}


byte_p xlr8_bytecode_start(tok_t t)
// ----------------------------------------------------------------------------
//   Return the first bytecode byte of a token's payload
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt || t >= xlr8_current_rt->tokens.size())
        return nullptr;
    return byte_p(xlr8_current_rt->tok(t));
}


byte_p xlr8_bytecode_end(tok_t t)
// ----------------------------------------------------------------------------
//   Return one-past-last byte of a token's bytecode payload
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt || t >= xlr8_current_rt->tokens.size())
        return nullptr;
    byte_p tp = xlr8_current_rt->tokens[t];
    size_t len = leb128<size_t>(tp);
    return byte_p(xlr8_current_rt->tok(t)) + len;
}


void xlr8_push_value(uintptr_t v)
// ----------------------------------------------------------------------------
//   Push a value on the bytecode evaluation stack
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        xlr8_current_rt->push(v);
}


uintptr_t xlr8_pop_value()
// ----------------------------------------------------------------------------
//   Pop a value from the bytecode evaluation stack
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        return xlr8_current_rt->pop();
    return 0;
}


void xlr8_store_global(byte g, byte s)
// ----------------------------------------------------------------------------
//   Store bytecode local s into global slot g
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return;
    runtime &rt = *xlr8_current_rt;
    if (size_t(g) < rt.globals.size())
        rt.globals[g] = value_t(rt.frame[s]);
}


void xlr8_load_global(byte d, byte g)
// ----------------------------------------------------------------------------
//   Load global slot g into bytecode local d
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return;
    runtime &rt = *xlr8_current_rt;
    if (size_t(g) < rt.globals.size())
        rt.frame[d] = value_t(rt.globals[g]);
}


void xlr8_set_flags(uint64_t flags)
// ----------------------------------------------------------------------------
//   Update runtime flags from the JIT flags register
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        xlr8_current_rt->flags = flags;
}


uint64_t xlr8_get_flags()
// ----------------------------------------------------------------------------
//   Return runtime flags for reloading the JIT flags register
// ----------------------------------------------------------------------------
{
    return xlr8_current_rt ? xlr8_current_rt->flags : 0;
}


void xlr8_save_jit_link(uintptr_t link)
// ----------------------------------------------------------------------------
//   Save the native return link for JIT epilogue
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        xlr8_current_rt->jit_link = link;
}


uintptr_t xlr8_load_jit_link()
// ----------------------------------------------------------------------------
//   Restore the native return link for JIT epilogue
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        return xlr8_current_rt->jit_link;
    return 0;
}


void xlr8_push_flags_val(uint64_t flags)
// ----------------------------------------------------------------------------
//   Push the runtime flags register on the bytecode stack
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
    {
        xlr8_current_rt->flags = flags;
        xlr8_current_rt->push(flags);
    }
}


uint64_t xlr8_pop_flags_val()
// ----------------------------------------------------------------------------
//   Pop flags from the bytecode stack into the runtime
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return 0;
    uint64_t flags = xlr8_current_rt->pop<uint64_t>();
    xlr8_current_rt->flags = flags;
    return flags;
}


int xlr8_sys(tok_t t, byte_p args)
// ----------------------------------------------------------------------------
//   Invoke a native syscall with bytecode arguments at args
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return 0;
    if (args)
        xlr8_current_rt->pc = args;
    else if (xlr8_sys_args_pc)
        xlr8_current_rt->pc = xlr8_sys_args_pc;

    return xlr8_current_rt->native(t) ? 1 : 0;
}


static uintptr_t xlr8_jit_addr(uintptr_t bc_pc)
// ----------------------------------------------------------------------------
//   Map a bytecode PC to a native code address, or 0 if unknown
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt || !xlr8_current_rt->jit_code)
        return 0;
    runtime &rt = *xlr8_current_rt;
    auto it = rt.jit_pc_off.find(bc_pc);
    if (it == rt.jit_pc_off.end())
    {
        auto next = rt.jit_pc_off.lower_bound(bc_pc);
        if (next == rt.jit_pc_off.end())
            return 0;
        it = next;
    }
    return uintptr_t(rt.jit_code) + it->second;
}


uintptr_t xlr8_after_sys(uintptr_t expected_next_pc)
// ----------------------------------------------------------------------------
//   If a sys native changed pc, return the native address to continue at
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return 0;
    uintptr_t pc = uintptr_t(xlr8_current_rt->pc);
    if (pc == expected_next_pc)
        return 0;
    return xlr8_jit_addr(pc);
}


uintptr_t xlr8_dispatch(byte s, uintptr_t table_pc)
// ----------------------------------------------------------------------------
//   Run dispatch table logic at table_pc and return native address for new pc
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return 0;
    runtime &rt = *xlr8_current_rt;
    rt.pc = byte_p(table_pc);
    value_t ref = value_t(rt.frame[s]);
    rt.pc = rt.dispatch(rt.pc, ref, std::greater_equal<intptr_t>());
    return xlr8_jit_addr(uintptr_t(rt.pc));
}


void xlr8_skip_sys_args(tok_t t, byte_p &pc)
// ----------------------------------------------------------------------------
//   Advance pc past the arguments of a sys call during translation
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return;

    runtime &rt = *xlr8_current_rt;
    text name = rt.as_text(t);
    if (name.empty())
        return;

    for (const native_skip_entry &entry : native_skip_table)
        if (name == entry.name)
        {
            skip_native_args(entry.pattern, pc);
            return;
        }
}
